def solve(kind, message):
    class Email:
        def send(self, text):
            return "email:" + text

    class Sms:
        def send(self, text):
            return "sms:" + text

    table = {"email": Email, "sms": Sms}
    if kind not in table:
        return "error"
    return table[kind]().send(message)
